/* ROLE_SONG_CLOUD_V1：每个角色单独配置；任务及密钥不进入音乐导出包。 */
function roleSongCloudConfig(cid){const cfg=S.settings&&S.settings.roleSongCloud&&S.settings.roleSongCloud[cid];return cfg&&cfg.url&&cfg.key?cfg:null;}
/* ROLE_SONG_QUOTA_VIEW_V1：只展示服务真实时长配额，不当成平台余额；旧服务保持可用。 */
function roleSongQuotaText(info){
  if(!info||info.unit!=='audio_seconds'||!/^\d{4}-\d{2}$/.test(String(info.period||'')))return '';
  const names=['limit','used','reserved','remaining'];if(names.some(k=>!Number.isSafeInteger(info[k])||info[k]<0))return '';
  if(info.used+info.reserved>Number.MAX_SAFE_INTEGER||info.remaining!==Math.max(0,info.limit-info.used-info.reserved))return '';
  const time=n=>Math.floor(n/60)+'分'+String(n%60).padStart(2,'0')+'秒';
  return info.period+'（UTC月）\n剩余 '+time(info.remaining)+' / 限额 '+time(info.limit)+'\n已用 '+time(info.used)+' · 制作中预占 '+time(info.reserved)+'\n这是时长配额，不是云平台账户余额。实际费用请查看云平台账单。';
}
async function roleSongCloudQuotaRefresh(cid,cfg){
  const el=$('#rsc_quota'),state=S,account=String(actId());if(!el)return;
  if(!cfg||!cfg.url||!cfg.key){el.textContent='连接服务后查看该服务提供的额度信息。';return;}
  if(cfg.quotaSupported!==true){el.textContent='此服务尚未提供可查询的时长配额；实际余额和费用请在自己的云平台查看。';return;}
  el.textContent='正在读取服务额度…';
  const live=()=>S===state&&String(actId())===account&&el.isConnected&&$('#rsc_quota')===el&&String(($('#rsc_role')||{}).value)===String(cid);
  try{const r=await roleSongCloudRequest(cfg,'/quota'),info=await r.json();if(!live())return;const text=roleSongQuotaText(info);el.textContent=text||'服务额度格式无法识别，请在自己的云平台核对；不会显示猜测余额。';}
  catch(_){if(live())el.textContent='暂时无法读取服务额度，请检查连接或到自己的云平台核对。';}
}
function roleSongSourceStamp(song){return JSON.stringify([song.id,song.roleSongOwner,song.src,song.fileSig,song.fileSize,song.roleSongHasAccompaniment]);}
function roleSongConvertCandidate(cid,query){if(!roleSongCloudConfig(cid)||!(S.contacts||[]).some(c=>c&&!c.deleted&&String(c.id)===String(cid)))return null;const songs=musicLibrarySongs('role',cid).filter(s=>s.roleSongReady!==true&&s.src),q=String(query||'').trim();if(/^(随机|随便|random)$/i.test(q))return songs.length?songs[Math.floor(Math.random()*songs.length)]:null;const exact=songs.find(s=>String(s.id)===q);if(exact)return exact;const key=musicKeyText(q),hits=songs.filter(s=>[s.title,...(Array.isArray(s.roleSongAliases)?s.roleSongAliases:[])].some(t=>key&&musicKeyText(t)===key));return hits.length===1?hits[0]:null;}
