function roleSongProgressHTML(song){if(!song||!song.roleSongOwner||song.roleSongReady===true)return '';const text=roleSongProgressText(song);return '<span data-role-song-progress="'+esc(song.id)+'" role="status" aria-live="polite" style="display:'+(text?'block':'none')+';font-size:11px;line-height:1.5;margin-top:4px;opacity:.85">'+esc(text)+'</span>';}
