function roleSongProgressPaint(){
  if(typeof document==='undefined'||typeof document.querySelectorAll!=='function')return;
  const songs=S.music&&S.music.songs||[];
  document.querySelectorAll('[data-role-song-progress]').forEach(el=>{const song=songs.find(s=>s.id===el.getAttribute('data-role-song-progress')),text=roleSongProgressText(song);el.textContent=text;el.style.display=text?'block':'none';});
  document.querySelectorAll('[data-role-song-make]').forEach(el=>{const song=songs.find(s=>s.id===el.getAttribute('data-role-song-make'));if(!song)return;const key=roleSongProgressKey(song),busy=_roleSongConversions.has(key),job=S.settings&&S.settings.roleSongJobs&&S.settings.roleSongJobs[key];el.disabled=busy;el.textContent=busy?'正在制作…':job?'继续查看制作结果':'制作他的翻唱';});
}
function roleSongProgressUpdate(song,phase,progress){
  const key=roleSongProgressKey(song),entry=_roleSongConversions.get(key);if(!entry||typeof entry!=='object')return;
  const allowed=['uploading','processing','reading','separating','converting','encoding','saving'];entry.phase=allowed.includes(phase)?phase:'processing';
  const total=Math.max(0,Math.min(12,Math.floor(Number(progress&&progress.total)||0))),completed=Math.max(0,Math.min(total,Math.floor(Number(progress&&progress.completed)||0)));entry.total=total;entry.completed=completed;
  const job=S.settings&&S.settings.roleSongJobs&&S.settings.roleSongJobs[key];if(job&&(job.phase!==entry.phase||job.total!==total||job.completed!==completed)){job.phase=entry.phase;job.total=total;job.completed=completed;save(300);}
  roleSongProgressPaint();
  if(!_roleSongProgressTimer&&typeof document!=='undefined'&&typeof document.querySelectorAll==='function')_roleSongProgressTimer=setInterval(roleSongProgressPaint,1000);
}
