async function roleSongConvertOpen(id,fromEditor){if(fromEditor&&!musicEditSave(id,true))return;const song=(S.music&&S.music.songs||[]).find(s=>s.id===id);if(!song||!song.roleSongOwner)return;if(song.roleSongReady===true)return toast('这是已完成的演唱，无需再次制作');if(!roleSongCloudConfig(song.roleSongOwner)){roleSongCloudModal(song.roleSongOwner);return;}try{const result=await roleSongConvert(song.roleSongOwner,id);if(result){closeModal();render();}}catch(e){toast(e.message||'翻唱制作失败，原曲已保留');}}
