async function roleSongSpeakMessage(m,c){if(!m||!m.roleSong||!c||c.deleted||String(c.id)!==String(m.roleSong.cid))return false;const state=S,account=String(actId()),live=()=>S===state&&String(actId())===account&&getC(c.id)===c&&!c.deleted;let url=m.audio&&await audioPlayableUrl(m.audio);if(!live())return false;if(!url){try{const replacement=await roleSongVoiceMessage(c.id,m.roleSong.id,live);if(!replacement||!live())return false;m.audio=replacement.audio;m.audioTs=replacement.audioTs;m.dur=replacement.dur;save();url=await audioPlayableUrl(m.audio);if(!live())return false;}catch(e){if(live())toast(e.message||'这段演唱音频不可用，请在音乐里补回文件');return false;}}if(url&&live()){voiceBarWant(m.id);playUrl(url);return true;}return false;}
