function musicDiscPickerHTML(discColor){const custom=discColor.startsWith('#'),customValue=custom?discColor:S.music.discCustomColor;return `<div class="music-disc-picker music-disc-picker-custom" role="group" aria-label="唱片颜色">${MUSIC_DISC_PRESETS.map(color=>`<button class="music-disc-choice${discColor===color?' on':''}" data-color="${color}" onclick="musicDiscColorSet('${color}')" aria-pressed="${discColor===color}"><i></i><span>${musicDiscColorName(color)}</span></button>`).join('')}<label class="music-disc-choice music-disc-custom-choice${custom?' on':''}" data-color="custom"><input type="color" value="${customValue}" aria-label="自定义唱片颜色" oninput="musicDiscColorInput(this.value)" onchange="musicDiscColorInput(this.value)"><i style="--custom-disc-preview:${customValue}"></i><span>自定义</span></label></div>`;}
function musicDiscSurface(){const color=musicDiscColor();if(!color.startsWith('#'))return{className:color,style:''};return{className:'custom',style:`--music-disc-custom:${color};--music-disc-light:${musicDiscColorBlend(color,'#ffffff',.58)};--music-disc-soft:${musicDiscColorBlend(color,'#ffffff',.24)};--music-disc-dark:${musicDiscColorBlend(color,'#000000',.42)};--music-disc-deep:${musicDiscColorBlend(color,'#000000',.68)}`};}
function musicDiscColorModal(){musicInit();const discColor=musicDiscColor();openModal(`<h3>唱片颜色</h3><div class="hint">唱片颜色独立保存，不跟随主屏主题。可使用快捷颜色，也可以点“自定义”选择任意颜色。</div><div class="music-disc-picker-modal">${musicDiscPickerHTML(discColor)}</div><button class="btn g" style="margin-top:10px" onclick="musicMenu()">返回播放页外观</button>`);}
function musicEnsureCurrent(){musicInit();const songs=(S.music.songs||[]).filter(s=>!s.mcpAccount||s.mcpAccount===String(actId()));if(!songs.length){_mCur=null;return null;}let cur=songs.find(s=>s.id===_mCur),wanted=(S.music.session&&S.music.session.songId)||S.music.lastSongId;if(!cur&&wanted)cur=songs.find(s=>s.id===wanted);if(!cur)cur=songs[0];_mCur=cur.id;return cur;}
function musicKeyText(s){return String(s||'').toLowerCase().replace(/[ \t\r\n"'“”‘’《》<>【】\[\]（）(){}.,，。！？!?、:：;；~～…\-—_·]/g,'');}
function musicFindSongByText(text){musicInit();const q=musicKeyText(text);if(!q)return null;let best=null,score=0,artistHit=[];
  (S.music.songs||[]).forEach(s=>{const t=musicKeyText(s.title),a=musicKeyText(s.artist),mix=musicKeyText((s.title||'')+(s.artist||''));let sc=0;
    if(t&&t.length>=2&&(q===t||q.includes(t)))sc=100+t.length;
    else if(t&&t.length===1&&(q===t||q.includes('听'+t)||q.includes('放'+t)||q.includes('切'+t)))sc=70;
    else if(mix&&mix.length>=3&&q.includes(mix))sc=80+mix.length;
    if(a&&q.includes(a))artistHit.push(s);
    if(sc>score){score=sc;best=s;}
  });
  if(best)return best;
  if(artistHit.length===1&&/(听|放|来一首|换|切)/.test(text||''))return artistHit[0];
  return null;}
function musicMirrorToWechat(cid,role,text){const c=getC(cid);if(!c||!text)return;const who=role==='user'?S.me.name:(role==='assistant'?(c.remark||c.name):'系统');
  msgs(cid).push({role:role==='assistant'?'assistant':'user',type:'sys',content:'🎧 一起听里，'+who+'：'+String(text).slice(0,160),time:Date.now(),id:uid(),_silent:true,_musicCtx:true});}
function musicSwitchSongForSession(song,cid,spoken){musicInit();const sess=S.music.session;if(!song||!sess||sess.cid!==cid)return false;
  if(sess.songId===song.id&&_mCur===song.id)return false;
  sess.songId=song.id;const line='已切到「'+(song.title||'这首歌')+'」';
  S.music.chat.push({cid,role:'sys',content:line,time:Date.now()});if(S.music.chat.length>200)S.music.chat=S.music.chat.slice(-200);
  musicMirrorToWechat(cid,'sys',line+(spoken?'，因为'+S.me.name+'说：'+spoken:''));
  mShowBub('r','切到 '+(song.title||'这首歌'));musicPlay(song.id);return true;}
