function mIDB(owner){return new Promise((res,rej)=>{let settled=false;const r=indexedDB.open(typeof privateScopedDatabaseName==='function'?privateScopedDatabaseName('yibeiMusic',owner):'yibeiMusic',1),fail=()=>{if(settled)return;settled=true;rej(r.error||new Error('Music storage unavailable'));};r.onupgradeneeded=e=>{try{e.target.result.createObjectStore('audio');}catch(_){}};r.onsuccess=e=>{if(settled){try{e.target.result.close();}catch(_){}return;}settled=true;const db=e.target.result;db.onversionchange=()=>{try{db.close();}catch(_){}};res(db);};r.onerror=fail;r.onblocked=fail;});}
function mPut(k,b,owner){return mIDB(owner).then(db=>new Promise((res,rej)=>{let tx;try{tx=db.transaction('audio','readwrite');tx.objectStore('audio').put(b,k);}catch(e){try{db.close();}catch(_){}rej(e);return;}const done=(ok,e)=>{try{db.close();}catch(_){}ok?res():rej((e&&e.target&&e.target.error)||tx.error||new Error('Music storage write failed'));};tx.oncomplete=()=>done(true);tx.onerror=e=>done(false,e);tx.onabort=e=>done(false,e);}));}
