const MUSIC_MANIFEST_KEY='__music_manifest_v1';
let _musicManifestWrite=Promise.resolve(true),_musicManifestQueued=null;
//@@ web
function musicManifestSnapshot(savedAt){if(!S.music||!Array.isArray(S.music.songs))return null;try{return{ver:1,savedAt:+savedAt||Date.now(),music:JSON.parse(JSON.stringify(S.music))};}catch(_){return null;}}
function musicManifestQueueSave(savedAt){const row=musicManifestSnapshot(savedAt);if(!row)return _musicManifestWrite;_musicManifestQueued=row;_musicManifestWrite=_musicManifestWrite.then(async()=>{while(_musicManifestQueued){const next=_musicManifestQueued;_musicManifestQueued=null;await mPut(MUSIC_MANIFEST_KEY,next);}return true;}).catch(()=>false);return _musicManifestWrite;}
