async function musicManifestRestore(){const row=await mGet(MUSIC_MANIFEST_KEY);if(!row||!row.music||!Array.isArray(row.music.songs))return false;const coreAt=+(S&&S._persistedAt)||0,manifestAt=+row.savedAt||0;if(manifestAt<=coreAt)return false;S.music=row.music;musicInit();return true;}
